(function(){
  'use strict';
  const M=window.SalesWorkbench, guest=document.body.dataset.salesMode==='guest', root=document.getElementById('swRoot'), dialog=document.getElementById('swDialog');
  let state, uid=sessionStorage.getItem('sw-staff')||'', route={}, dirty=false, booking=null, step=1, previous='', query='', filter='全部', customerTab='客户', modalResolve;
  let storageOK=true;
  try{const saved=JSON.parse(localStorage.getItem(M.KEY));state=saved?.version===1?saved:M.seed();}catch{state=M.seed();}
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=M.money, code=(v,n=4)=>v?v.slice(0,2)+'••••'+v.slice(-n):'待补充';
  function save(){try{localStorage.setItem(M.KEY,JSON.stringify(state));}catch{storageOK=false;toast('浏览器未能保存，当前操作只保留在本次页面。');}}
  function toast(v){const el=document.getElementById('swToast');el.textContent=v;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
  function icon(name){const paths={home:'M3 10 12 3l9 7M5 9v11h14V9M9 20v-7h6v7',product:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M15 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',order:'M6 3h12v18l-3-2-3 2-3-2-3 2V3M9 7h6M9 11h6M9 15h3',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',clock:'M12 8v4l3 2M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',wallet:'M3 5h16v15H3zM3 5l13-3v3M14 11h7v5h-7z',check:'m5 12 4 4 10-10',file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6',share:'M12 16V3m-4 4 4-4 4 4M6 11H3v10h18V11h-3',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6',palm:'M13 21c-1-5 0-10 2-15M15 6C12 0 5 1 3 5c5-1 9-1 12 1ZM15 6c1-6 6-6 8-3-3 0-6 1-8 3ZM15 6c5-1 8 2 8 6-3-3-5-4-8-6ZM15 6c-6 0-9 4-8 8 2-4 4-6 8-8ZM3 22c4-3 14-3 18 0',mountain:'m2 20 7-13 5 9 3-6 5 10ZM7 11l2 2 2-2M15 5h.01',sun:'M12 3v2M12 19v2M3 12h2M19 12h2m-2-7-1.5 1.5M6.5 17.5 5 19m0-14 1.5 1.5M17.5 17.5 19 19M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',alert:'M12 8v5M12 17h.01M3 21h18L12 3Z',logout:'M9 3H3v18h6M9 12h12m-4-4 4 4-4 4'};return `<svg class="sw-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;}
  const btn=(text,action,kind='',attrs='')=>`<button type="${action==='submit'?'submit':'button'}" class="sw-button ${kind}" data-action="${action}" ${attrs}>${text}</button>`;
  const link=(text,action,attrs='')=>`<button type="button" class="sw-link" data-action="${action}" ${attrs}>${text}</button>`;
  const pill=(text,tone='')=>`<span class="sw-pill ${tone}">${e(text)}</span>`;
  const field=(label,name,value='',type='text',attrs='')=>`<label class="sw-field"><span>${label}</span><input name="${name}" type="${type}" ${type==='file'?'':`value="${e(value)}"`} ${attrs}></label>`;
  const select=(label,name,items,value='',attrs='')=>`<label class="sw-field"><span>${label}</span><select name="${name}" ${attrs}>${items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`;}).join('')}</select></label>`;
  const area=(label,name,value='',attrs='')=>`<label class="sw-field"><span>${label}</span><textarea name="${name}" ${attrs}>${e(value)}</textarea></label>`;
  const check=(label,name='checked')=>`<label class="sw-check"><input type="checkbox" name="${name}"><span>${label}</span></label>`;
  const error=()=>'<div class="sw-form-error" role="alert"></div>';
  const facts=items=>`<dl class="sw-facts">${items.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
  const section=(title,right='')=>`<div class="sw-section"><h2>${title}</h2>${right}</div>`;
  const notice=(text,tone='')=>`<div class="sw-notice ${tone}">${text}</div>`;
  const empty=(title,sub='',action='')=>`<div class="sw-empty">${icon('file')}<h3>${title}</h3><p class="sw-small">${sub}</p>${action}</div>`;
  const c=id=>M.customer(state,uid,id), o=()=>M.order(state,uid,route.id);
  function titleBar(title,back=true){return `<header class="sw-header">${back?`<button class="sw-back" data-action="back">${icon('back')}返回</button>`:'<span></span>'}<h1>${title}</h1><span class="sw-header-meta">凯撒旅游</span></header>`;}
  function nav(){return `<nav class="sw-nav" aria-label="主要功能">${[['home','home','工作台'],['products','product','产品'],['customers','users','客户'],['orders','order','订单']].map(([v,i,t])=>`<button data-go="${v}" class="${route.view===v?'active':''}" ${route.view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
  function line(title,sub,action,id='',ic='file',tone=''){return `<button class="sw-line" data-action="${action}" data-id="${e(id)}"><span class="sw-task-icon ${tone}">${icon(ic)}</span><span class="sw-line-body"><strong>${title}</strong><small>${sub}</small></span><span class="sw-chevron">${icon('chevron')}</span></button>`;}
  function parse(){const [view,qs]=(location.hash.slice(1)|| (guest?'recommend':'home')).split('?');return {view,...Object.fromEntries(new URLSearchParams(qs))};}
  function go(view,params={},replace=false){if(dirty&&!confirm('当前内容未保存，确认离开吗？'))return;dirty=false;query='';filter='全部';const hash=view+(Object.keys(params).length?'?'+new URLSearchParams(params).toString():'');if(replace){history.replaceState(null,'','#'+hash);render();}else if(location.hash==='#'+hash)render();else location.hash=hash;}
  function back(){if(guest){go(new URLSearchParams(location.search).has('share')?'recommend':'guest-home');return;}const targets={product:'products',share:'product',booking:'products',customer:'customers','new-customer':'customers',intent:'customer','edit-intent':'customer',consult:'home',order:'orders',claim:'order',contract:'order',materials:'order',travel:'order',account:'home',applications:'home'};const target=targets[route.view]||'home';go(target,['claim','contract','materials','travel'].includes(route.view)?{id:route.id}:route.view==='intent'||route.view==='edit-intent'?{id:route.cid||state.intents.find(x=>x.id===route.id)?.customerId}:route.view==='share'?{id:route.id}:{});}
  function confirmDialog(title,text){dialog.innerHTML=`<h2>${title}</h2><p>${text}</p><div class="sw-buttons">${btn('取消','dialog-cancel')}${btn('确认','dialog-ok','sw-primary')}</div>`;dialog.showModal();return new Promise(resolve=>modalResolve=resolve);}
  function guestURL(params){const url=new URL('guest.html',location.href);url.search=new URLSearchParams(params).toString();url.hash='';return url.href;}
  async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制，可粘贴给客户');}catch{dialog.innerHTML=`<h2>复制内容</h2><p>当前浏览器限制自动复制，可长按选择下方内容。</p><textarea class="sw-code sw-block" rows="5" readonly>${e(text)}</textarea><div class="sw-buttons">${btn('关闭','dialog-cancel','sw-primary')}</div>`;dialog.showModal();}}
  function login(){return `<div class="sw-login"><div class="sw-brand"><span class="sw-logo">${icon('sun')}</span><span>凯撒旅游<small>销售工作台</small></span></div><h1>随时接待，<br>从容办理。</h1><p class="sw-small">使用员工身份，继续您的客户与订单。</p><div class="sw-login-users">${state.staff.map(a=>`<button data-action="login-user" data-id="${a.id}">${e(a.name)}${a.active?'':'（停用）'}</button>`).join('')}</div><form data-form="login">${error()}${field('员工手机号','phone','13800000001','tel','autocomplete="tel" maxlength="11"')}${field('验证码','code','123456','text','inputmode="numeric" maxlength="6"')}${btn('进入工作台','submit','sw-primary sw-block')}<p class="sw-footer">业务原型 · 演示验证码 123456<br>仅使用演示资料，不发送真实短信</p></form></div>`;}
  function home(){const a=M.actor(state,uid),orders=state.orders.filter(x=>x.owner===uid&&x.status!=='已取消'),tasks=M.tasks(state,uid),drafts=state.drafts.filter(x=>x.owner===uid);return `<div class="sw-greeting"><div class="sw-row"><span class="sw-small">9月28日，星期一</span><button class="sw-account" data-go="account"><span class="sw-avatar">${e(a.name.slice(-1))}</span></button></div><h1>上午好，${e(a.name)}</h1><p class="sw-small">${e(a.company)} · ${e(a.store)}</p></div><section class="sw-overview"><div class="sw-row"><h3>今天的工作</h3>${pill('本人业务','blue')}</div><div class="sw-metrics"><div><strong>${tasks.length}</strong><small>待处理事项</small></div><div><strong>${state.intents.filter(x=>x.owner===uid&&!['已关闭','已转订单'].includes(x.stage)).length}</strong><small>跟进中意向</small></div><div><strong>${orders.filter(x=>x.created.startsWith('2026-09')).length}</strong><small>本月新订单</small></div></div></section><div class="sw-quick"><button data-go="products">${icon('search')}查产品 · 发推荐</button><button data-go="new-customer">${icon('plus')}接待新客户</button></div>${section('优先处理',link('我的申请','applications'))}<div class="sw-card">${tasks.length?tasks.map(t=>line(e(t.title),e(t.detail),t.view,t.id,t.view==='claim'?'wallet':t.view==='intent'?'clock':'file',t.tone)).join(''):empty('今天的事项已处理','新的业务结果会在这里呈现。')}</div>${drafts.length?section('继续预订')+`<div class="sw-card">${drafts.map(d=>line(e(d.customerId?c(d.customerId).name:'尚未选择客户'),e(state.products.find(x=>x.id===d.productId)?.name)+' · 未提交','resume',d.id,'order')).join('')}</div>`:''}${section('近期订单',link('全部订单','orders'))}${orderRows(orders.slice(0,2))}<p class="sw-footer">订单按创建月份统计 · 收款与合同分别核对</p>`;}
  function products(){let list=state.products.filter(x=>x.active&&x.allowed.includes(uid));const params=route.cid?`data-cid="${e(route.cid)}" data-iid="${e(route.iid||'')}"`:'';return `${route.cid?`<div class="sw-context">推荐给 ${e(c(route.cid).name)}<span>${route.iid?'本次意向':''}</span></div>`:''}<div class="sw-search">${icon('search')}<input data-search="products" placeholder="产品名称、目的地" value="${e(query)}" aria-label="搜索产品"></div><div class="sw-filter-row"><select data-filter="availability" aria-label="余位筛选"><option>全部日期</option><option>有位可订</option><option>二次确认</option></select><input type="date" data-filter="date" aria-label="出发日期" min="${M.TODAY}"><input type="number" data-filter="budget" aria-label="成人单价上限" placeholder="成人预算上限"><select data-filter="destination" aria-label="目的地"><option>全部目的地</option><option>三亚</option><option>云南</option><option>北京</option></select></div><div id="productResults" class="sw-card">${list.map(p=>productRow(p,params)).join('')}</div><p class="sw-footer">价格按所选日期及规格核对</p>`;}
  function productRow(p,params=''){return `<button class="sw-product-row" data-action="product" data-id="${p.id}" ${params}><span class="sw-product-art ${p.id}">${icon(p.id==='sanya'?'palm':'mountain')}</span><span class="sw-product-info"><h3>${e(p.name)}</h3><p>${e(p.from)}出发 · ${p.days}天 · ${e(p.theme)}</p><div class="sw-row"><span class="sw-price">${money(p.price)}<small>起 / 人</small></span>${pill(p.slots.some(x=>x.stock>0)?'有可售团期':'暂无余位')}</div></span></button>`;}
  function hero(p){return `<div class="sw-hero"><div class="sw-tiny">凯撒精选 · ${e(p.theme)}</div><h1>${e(p.name)}</h1><p>${e(p.subtitle)}</p>${icon(p.id==='sanya'?'palm':'mountain')}</div>`;}
  function trip(p){return `<div class="sw-card sw-pad">${p.itinerary.map(([t,d],i)=>`<details class="sw-day" ${i===0?'open':''}><summary><strong>第${i+1}天</strong>${e(t)}</summary><p>${e(d)}</p></details>`).join('')}</div>${section('费用与退改')}<div class="sw-card sw-pad sw-stack"><div><h3>费用包含</h3><p class="sw-small">${e(p.included)}</p></div><div><h3>费用不含</h3><p class="sw-small">${e(p.excluded)}</p></div><div><h3>退改约定</h3><p class="sw-small">${e(p.refund)}</p></div></div>`;}
  function productPage(){const p=M.product(state,uid,route.id);return `${route.cid?`<div class="sw-context">本次客户 · ${e(c(route.cid).name)}</div>`:''}${hero(p)}<div class="sw-tags">${p.highlights.map(x=>`<span>${e(x)}</span>`).join('')}</div><div class="sw-card sw-pad"><div class="sw-row"><h2>选择出发日期</h2><span class="sw-small">${e(p.from)}出发</span></div>${p.slots.map(s=>`<label class="sw-check"><input type="radio" name="slot" value="${s.id}" ${route.slot===s.id?'checked':''} ${s.stock===0?'disabled':''}><span><strong>${s.date}</strong>　${s.stock===0?'已售罄':`余位 ${s.stock}`}<span class="sw-small"> · ${s.mode}${s.rules?'':' · 条件待确认'}</span></span></label>`).join('')}<div class="sw-row sw-quote-total"><span class="sw-price">${money(p.price)}<small>成人 / 人</small></span><span class="sw-small">儿童占床 ${money(p.childPrice)}</span></div><p class="sw-tiny">双人间；单人数需单房差 ${money(p.single)}。以本团期条款为准。</p></div>${section('行程安排')}${trip(p)}<div class="sw-dock">${btn(icon('share')+'推荐分享','share-start','',`data-id="${p.id}"`)}${btn('预订','book-start','sw-primary',`data-id="${p.id}"`)}</div>`;}
  function sharePage(){const p=M.product(state,uid,route.id),done=route.sid&&M.shareView(state,route.sid),url=done?guestURL({share:done.share.id}):'';if(done)return `<div class="sw-result"><div class="sw-result-icon">${icon('check')}</div><h1>推荐内容已准备</h1><p class="sw-small">预览确认后，再分享给客户。</p></div>${hero(p)}<div class="sw-card sw-pad">${facts([['推荐内容',done.share.kind==='quote'?'具体出行报价':'产品介绍'],['顾问',e(M.actor(state,uid).name)],['报价',done.share.kind==='quote'?money(done.share.total):money(p.price)+'起']])}<div class="sw-code">${e(url)}</div><div class="sw-buttons">${btn('复制链接','copy','',`data-value="${e(url)}"`)}<a class="sw-button sw-primary" data-guest-link href="${e(url)}" target="_blank" rel="noopener">游客预览</a></div></div>${notice('分享仅提供产品和报价信息，余位与价格在预订时再次核对。')}`;return `${hero(p)}<form data-form="share" class="sw-card sw-pad">${error()}${select('推荐内容','kind',[['intro','产品介绍'],['quote','具体出行报价']],route.slot?'quote':'intro')}${select('出发日期（具体报价必选）','slotId',[['','请选择日期'],...p.slots.filter(x=>x.stock>0).map(x=>[x.id,x.date+' · '+x.mode])],route.slot||'')}<div class="sw-two">${field('成人','adults',2,'number','min="1" max="6"')}${field('儿童占床','children',0,'number','min="0" max="4"')}</div>${select('推荐客户','customerId',[['','公开产品推荐'],...state.customers.filter(x=>x.owner===uid).map(x=>[x.id,x.name])],route.cid||'')}<p class="sw-small">客户版包含行程、费用、退改及您的联系信息。指定客户的报价需要核对客户身份后查看。</p>${btn('生成对客推荐','submit','sw-primary sw-block')}</form>`;}
  function customers(){return `<div class="sw-row"><div class="sw-search sw-line-body">${icon('search')}<input data-search="customers" placeholder="姓名或手机号" aria-label="搜索客户"></div>${link('新增','new-customer')}</div><div class="sw-tabs">${['客户','意向'].map(t=>`<button data-action="customer-tab" data-value="${t}" class="${customerTab===t?'active':''}">${t}</button>`).join('')}</div><div class="sw-card" id="customerResults">${customerTab==='客户'?state.customers.filter(x=>x.owner===uid).map(x=>customerRow(x)).join(''):state.intents.filter(x=>x.owner===uid).map(i=>line(e(c(i.customerId).name)+' · '+e(i.destination),e(i.stage)+' · '+(i.date||'日期待定'),'intent',i.id,'clock')).join('')||empty('暂无意向','从客户详情记录本次出行需求。')}</div>`;}
  function customerRow(x){return `<button class="sw-line" data-action="customer" data-id="${x.id}"><span class="sw-avatar">${e(x.name.slice(0,1))}</span><span class="sw-line-body"><strong>${e(x.name)}</strong><small>${e(code(x.phone))} · ${state.orders.filter(o=>o.owner===uid&&o.customerId===x.id).length}笔订单</small></span>${icon('chevron')}</button>`;}
  function newCustomer(){return `<form data-form="customer" class="sw-card sw-pad">${error()}${field('客户姓名','name','','text','maxlength="30"')}${field('手机号','phone','','tel','maxlength="11"')}${area('出行偏好或备注','note')}${btn('保存客户','submit','sw-primary sw-block')}</form>`;}
  function customerPage(){const x=c(route.id),intents=state.intents.filter(i=>i.owner===uid&&i.customerId===x.id);return `<div class="sw-card sw-pad"><div class="sw-row sw-row-start"><span class="sw-avatar">${e(x.name[0])}</span><div><h1>${e(x.name)}</h1><span class="sw-small">${e(x.phone)}</span></div></div><p class="sw-small sw-inline-meta">${e(x.note||'暂无出行偏好')}</p><div class="sw-buttons">${btn('记录需求','new-intent','',`data-id="${x.id}"`)}${btn('选产品','recommend','sw-primary',`data-cid="${x.id}"`)}</div></div>${section('本次出行意向')}<div class="sw-card">${intents.map(i=>line(e(i.destination)+' · '+i.pax+'人',e(i.stage)+' · '+(i.date||'日期待定'),'intent',i.id,'clock')).join('')||empty('尚未记录意向')}</div>${section('常用同行人')}<div class="sw-card">${x.companions.map(p=>line(e(p.name),e(code(p.phone))+' · 证件'+(p.identity?'已留存':'待补'),'noop','','users')).join('')}</div>${section('历史订单')}${orderRows(state.orders.filter(o=>o.owner===uid&&o.customerId===x.id))}`;}
  function intentPage(){const i=state.intents.find(x=>x.id===route.id&&x.owner===uid);if(!i)throw Error('未找到本人意向。');const cust=c(i.customerId);return `<div class="sw-card sw-pad"><div class="sw-row"><h1>${e(cust.name)}的出行需求</h1>${pill(i.stage,'blue')}</div>${facts([['目的地',e(i.destination)],['出行日期',e(i.date||'日期待定')],['出行人数',i.pax+'人'],['预算',i.budget?money(i.budget):'待沟通'],['回访时间',e(i.follow||'未安排')]])}<p class="sw-small">${e(i.note)}</p><div class="sw-buttons">${btn('编辑需求','edit-intent','',`data-id="${i.id}" data-cid="${cust.id}"`)}${btn('推荐产品','recommend','sw-primary',`data-cid="${cust.id}" data-iid="${i.id}" ${i.stage==='已关闭'?'disabled':''}`)}</div></div>${i.orders.length?section('关联订单')+orderRows(state.orders.filter(o=>o.owner===uid&&i.orders.includes(o.id))):''}<form class="sw-card sw-pad" data-form="follow">${error()}<h2>本次跟进</h2>${area('沟通结果','text')}${field('下次回访','follow',i.follow,'date')}${select('处理结果','result',i.orders.length?['继续跟进']:['继续跟进','关闭意向','恢复跟进'])}${btn('保存跟进','submit','sw-primary sw-block')}</form>${section('跟进记录')}<div class="sw-card sw-pad"><ul class="sw-timeline">${i.history.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div>`;}
  function intentEdit(){const i=route.id&&state.intents.find(x=>x.id===route.id&&x.owner===uid),cust=c(route.cid||i?.customerId);return `<div class="sw-context">${e(cust.name)} · 本次出行</div><form class="sw-card sw-pad" data-form="intent">${error()}${field('目的地','destination',i?.destination||'')}${field('出行日期（未定可留空）','date',i?.date||'','date',`min="${M.TODAY}"`)}<div class="sw-two">${field('人数','pax',i?.pax||2,'number','min="1" max="10"')}${field('预算（元，未定可留空）','budget',i?.budget||'','number','min="0"')}</div>${area('客户需求','note',i?.note||'')}${field('下次回访','follow',i?.follow||M.TODAY,'date')}${btn('保存本次需求','submit','sw-primary sw-block')}</form>`;}
  function consultation(){const x=state.consultations.find(x=>x.owner===uid&&x.id===route.id);if(!x)throw Error('未找到待接待咨询。');const v=M.shareView(state,x.shareId);return `<div class="sw-card sw-pad"><div class="sw-row"><h1>${e(x.name)}</h1>${pill(x.status,'blue')}</div>${facts([['联系方式',e(x.phone)],['推荐产品',e(v.product.name)],['出行日期',x.date||'日期待定'],['人数',x.pax+'人'],['咨询内容',e(x.note||'暂无补充')],['来源',e(v.staff?.name||'原顾问')+'的产品推荐']])}${notice('接待时核对客户归属，同一客户可记录不同出行需求。')}${btn(x.intentId?'查看本次意向':'接待并记录意向','accept-consult','sw-primary sw-block',`data-id="${x.id}"`)}</div>`;}
  function startBooking(pid,slot,cid,iid){const p=M.product(state,uid,pid);booking={productId:pid,slotId:slot||p.slots.find(s=>s.stock>0)?.id,adults:2,children:0,customerId:cid||'',intentId:iid||'',people:[],mode:'已确认',draftId:'DRAFT-'+Date.now(),accept:false};if(iid){const i=state.intents.find(x=>x.id===iid&&x.owner===uid);if(i){booking.adults=Math.min(6,i.pax);booking.shareId=i.shareId||'';}}syncQuote();setPeople();step=1;go('booking');}
  function syncQuote(){const q=M.quote(state,uid,booking);Object.assign(booking,q);if(q.confirmation==='二次确认')booking.mode='待确认';}
  function setPeople(){const cust=booking.customerId?c(booking.customerId):null;booking.people=Array.from({length:Number(booking.adults)+Number(booking.children)},(_,i)=>{const old=booking.people?.[i],known=cust?.companions?.[i];return old||known?M.copy(old||known):{name:'',phone:'',identity:''};});}
  function readBooking(form){const v=Object.fromEntries(new FormData(form));if(step===1){booking.slotId=v.slotId;booking.adults=Number(v.adults);booking.children=Number(v.children);}if(step===2){booking.customerId=v.customerId;booking.people=booking.people.map((t,i)=>({...t,name:v['name'+i]||'',phone:v['phone'+i]||'',identity:v['identity'+i]||''}));}if(step===3){booking.mode=v.mode;booking.accept=!!v.accept;}}
  function cost(q){return facts([['成人',`${q.adults} × ${money(state.products.find(p=>p.id===q.productId).price)}`],...(q.children?[['儿童占床',`${q.children} × ${money(state.products.find(p=>p.id===q.productId).childPrice)}`]]:[]),['单房差',money(q.supplement)],['订单合计',`<strong>${money(q.total)}</strong>`]]);}
  function bookingPage(){if(!booking){return empty('尚未选择预订产品','从产品详情选择团期后开始。',btn('查看产品','products','sw-primary'));}const p=M.product(state,uid,booking.productId),items=[['1','出行选择'],['2','客户资料'],['3','核对提交']];let body='';if(step===1)body=`${select('出发日期','slotId',p.slots.map(x=>[x.id,x.date+(x.stock?' · 余'+x.stock+'位':' · 已售罄')]),booking.slotId)}<div class="sw-two">${field('成人','adults',booking.adults,'number','min="1" max="6"')}${field('儿童占床','children',booking.children,'number','min="0" max="4"')}</div>${notice('住宿为标准双人间，单人数需单房差 '+money(p.single)+'。所选儿童价格包含占床。')}`;if(step===2)body=`${select('订单客户','customerId',[['','请选择本人客户'],...state.customers.filter(x=>x.owner===uid).map(c=>[c.id,c.name+' · '+code(c.phone)])],booking.customerId)}${booking.people.map((t,i)=>`<div class="sw-divider"></div><h3>游客${i+1} · ${i<booking.adults?'成人':'儿童'}</h3>${field('姓名','name'+i,t.name)}${field('手机号','phone'+i,t.phone,'tel','maxlength="11"')}${field('身份证号（可后补）','identity'+i,t.identity,'text','maxlength="24"')}`).join('')}<p class="sw-small">常用同行资料带入后仍需核对；证件未齐可以先预订，签约前须补齐。未成年人签署需核对监护关系。</p>`;if(step===3)body=`${cost(booking)}${facts([['客户',e(c(booking.customerId).name)],['日期',booking.date],['资源确认',e(booking.confirmation)],['付款安排',booking.rules?`本团期人均定金 ${money(2000)}，余款出发前收齐`:'本团期付款条件待确认']])}${select('预订方式','mode',booking.confirmation==='二次确认'?['待确认',...(booking.rules?['预留','占位']:[])]:['已确认','预留','占位','待确认'],booking.mode)}${booking.rules?notice('本团期演示条款：预留／占位保留至2026-09-29 18:00，已产生资金、合同或确认资源时须另行核对。'):notice('本团期保留及付款条件待确认，仅可提交待确认或保存草稿。','warn')}${check('已核对客户、游客、费用、退改及本单付款安排。','accept')}`;return `<div class="sw-steps">${items.map(([n,t])=>`<span class="${step===Number(n)?'active':''}"><b>${n}</b>${t}</span>`).join('')}</div><div class="sw-context">${e(p.name)}<span>${booking.date}</span></div><form data-form="booking" class="sw-card sw-pad">${error()}${body}<div class="sw-buttons">${step>1?btn('上一步','booking-prev'):btn('保存草稿','save-booking')}${btn(step===3?'提交预订':'下一步','submit','sw-primary')}</div>${step>1?link('保存草稿，稍后继续','save-booking'):''}</form>`;}
  function orderRows(list){return `<div class="sw-card sw-order-list">${list.length?list.map(x=>`<button class="sw-line" data-action="order" data-id="${x.id}"><span class="sw-line-body"><div class="sw-row"><span class="sw-order-number">${x.id}</span>${pill(x.status,x.status==='已确认'?'green':'orange')}</div><h3>${e(x.title)}</h3><small>${e(x.contact)} · ${x.people.length}人 · ${x.date}出发</small><div class="sw-row sw-inline-meta"><span>${x.status==='已确认'?'待收':'预计金额'} ${money(x.status==='已确认'?M.amounts(x).unpaid:x.total)}</span>${icon('chevron')}</div></span></button>`).join(''):empty('暂无符合条件的订单','可从产品详情开始预订。')}</div>`;}
  function orders(){return `<div class="sw-search">${icon('search')}<input data-search="orders" aria-label="搜索订单" placeholder="订单号、客户、产品" value="${e(query)}"></div><div class="sw-tabs">${['全部','已确认','待确认','预留','占位','已取消'].map(x=>`<button data-action="order-filter" data-value="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div><div id="orderResults">${orderRows(state.orders.filter(x=>x.owner===uid&&(filter==='全部'||x.status===filter)))}</div>`;}
  function orderPage(){const x=o(),m=M.amounts(x);return `<div class="sw-card sw-pad"><div class="sw-row"><span class="sw-order-number">${x.id}</span>${pill(x.status,x.status==='已确认'?'green':'orange')}</div><h1>${e(x.title)}</h1><p class="sw-small sw-inline-meta">${e(x.contact)} · ${x.people.length}人 · ${x.date}出发</p><div class="sw-money-grid"><div><span>${x.status==='已确认'?'订单应收':'预计金额'}</span><strong>${money(x.total)}</strong></div><div><span>已确认收款</span><strong>${money(m.paid)}</strong></div><div><span>${x.status==='已确认'?'待收':'尚未收取'}</span><strong class="due">${money(m.unpaid)}</strong></div></div>${m.pending?notice('认款 '+money(m.pending)+' 待财务复核，不计已确认收款。'):''}${m.inflight?notice('付款 '+money(m.inflight)+' 结果待核对，请查询原笔结果。','warn'):''}${x.holdUntil?notice('保留截止：'+x.holdUntil,'warn'):''}${x.status==='待确认'?notice('资源：'+x.resource+' · 计调 周宁'+(x.resource==='无位'?'，请与客户核对替代日期。':''),'warn'):''}${['待确认','预留','占位'].includes(x.status)?`<div class="sw-buttons">${['预留','占位'].includes(x.status)?btn('释放','release','',`data-id="${x.id}"`):''}${btn('核对并确认订单','confirm-order','sw-primary',`data-id="${x.id}"`)}</div>`:''}</div>${section('本单办理')}<div class="sw-card">${line('收款与认款',m.pending?'待财务复核 '+money(m.pending):m.unpaid?'待收 '+money(m.unpaid):'款项已收齐','claim',x.id,'wallet')}${line('合同办理',e(x.contract.status==='未准备'?'签署资料待核对':x.contract.status),'contract',x.id,'file')}${line('游客资料',x.people.filter(p=>p.material.status==='已核对').length+'/'+x.people.length+'人已核对','materials',x.id,'users')}${line('出行资料',x.notice?'已发布 · 第'+x.notice.version+'版':'出团通知尚未发布','travel',x.id,'product')}</div>${x.status!=='已取消'?`<div class="sw-card sw-pad"><h3>让客户继续办理</h3><p class="sw-small">客户可在本单入口查看付款、签署和资料进度。</p>${guestLinks(x)}</div>`:''}${section('费用明细')}<div class="sw-card sw-pad">${cost(x)}${facts([['签约公司',e(x.company)],['收款公司',e(x.company)],['销售顾问',e(M.actor(state,uid).name)]])}</div>${section('办理记录')}<div class="sw-card sw-pad"><ul class="sw-timeline">${x.logs.map(l=>`<li>${e(l)}</li>`).join('')}</ul></div>`;}
  function guestLinks(x,scope='order'){return `<div class="sw-stack">${x.people.filter(t=>t.kind==='成人').map(p=>`<div class="sw-row sw-inline-meta"><span>${e(p.name)}<span class="sw-tiny"> · ${scope==='docs'?'资料':scope==='sign'?'签署':'本人办理'}</span></span>${link('取得入口','grant',`data-id="${x.id}" data-person="${p.id}" data-scope="${scope}"`)}</div>`).join('')}</div>`;}
  function claimPage(){const x=o(),m=M.amounts(x),prior=x.claims.find(c=>c.id===route.claim)||x.claims.find(c=>c.status==='退回补充');return `<div class="sw-context">${e(x.contact)} · ${x.id}</div><div class="sw-card sw-pad">${facts([['收款公司',e(x.company)],['已确认收款',money(m.paid)],['待复核',money(m.pending)],['可新申请金额',money(m.available)]])}</div>${section('收款记录')}<div class="sw-card">${x.payments.map(p=>`<div class="sw-pad"><div class="sw-row"><strong>${money(p.amount)}</strong>${pill(p.status,p.status==='成功'?'green':'orange')}</div><p class="sw-small">${p.id} · ${p.kind||'订单收款'}</p></div>`).join('')}${x.claims.map(p=>`<div class="sw-pad"><div class="sw-row"><strong>${money(p.amount)}</strong>${pill(p.status,p.status==='已确认'?'green':'orange')}</div><p class="sw-small">${p.id} · ${e(p.payer)} · ${e(p.reference)}</p>${p.reason?notice(e(p.reason),'warn'):''}</div>`).join('')||empty('暂无认款记录')}</div>${m.available>0&&x.status!=='已取消'?`<form class="sw-card sw-pad" data-form="claim" data-claim="${prior?.id||''}">${error()}<h2>${prior?'补充原认款申请':'登记认款'}</h2>${prior?`<p class="sw-small">${prior.id} · 保留原申请与退回记录</p>`:''}${field('认领金额（元）','amount',prior?.amount||m.available,'number',`min="0.01" max="${m.available}" step="0.01"`)}${field('付款人','payer',prior?.payer||x.contact)}${field('银行流水号','reference',prior?.reference||'')}${field('付款凭据','proof','','file','accept="image/*,.pdf"')}${prior?.proof?`<p class="sw-small">原凭据：${e(prior.proof)}</p>`:''}${area('代付关系（非联系人付款必填）','relation',prior?.relation||'')}${btn(prior?'补充并重新提交':'提交财务复核','submit','sw-primary sw-block')}</form>`:notice('当前无可新认金额，请查看已有付款与认款结果。')}${section('客户付款入口')}<div class="sw-card sw-pad">${guestLinks(x)}</div>`;}
  function contractPage(){const x=o(),k=x.contract;return `<div class="sw-context">${e(x.contact)} · ${x.id}</div><div class="sw-contract-paper"><h2>团队境内旅游合同</h2><p class="sw-small">${e(x.company)} · 第${k.version}版</p><div class="sw-divider"></div><div class="sw-row"><span class="sw-small">本份合同金额</span><strong>${money(x.total)}</strong></div><p class="sw-small sw-inline-meta">${e(x.title)} · ${x.date} · ${x.people.length}人</p>${pill(k.status,k.status==='已签署'?'green':'orange')}${k.reason?notice(e(k.reason),'warn'):''}<div class="sw-divider"></div>${facts([['签署人',x.people.map(p=>e(p.name)).join('、')],['行程附件',e(x.title)+' · '+state.products.find(p=>p.id===x.productId).days+'日行程'],['费用附件','团款与单房差明细'],['退改依据','本团期适用条款及资源损失核对']])}${link('预览合同与附件','contract-preview')}</div>${k.status==='未准备'||k.status==='审核退回'?`<form data-form="contract" class="sw-card sw-pad">${error()}${check('已核对签约公司、签署人、游客证件、金额与行程费用附件。')}${btn(k.status==='审核退回'?'补正并重新提交':'提交合同审核','submit','sw-primary sw-block')}</form>`:k.status==='待审核'?notice('合同经办审核中，结果会在本单返回。'):k.status==='待签署'?`<div class="sw-buttons">${btn('发起签署','send-contract','sw-primary sw-block')}</div>`:`<div class="sw-card sw-pad">${k.platform==='结果待核对'?notice('发起结果待核对，请先查询原申请，不要重复发起。','warn')+btn('查询原合同结果','refresh-result'):''}${k.signers.map(p=>`<div class="sw-row sw-inline-meta"><span>${e(p.name)}</span>${pill(p.status,p.status==='已签署'?'green':'orange')}</div>`).join('')}<div class="sw-row sw-inline-meta"><span>我方签章</span>${pill(k.seal?'已完成':'未完成',k.seal?'green':'orange')}</div>${guestLinks(x,'sign')}</div>`}`;}
  function materialsPage(){const x=o();return `<div class="sw-context">${e(x.title)} · ${x.people.length}位游客</div>${x.people.map(p=>{const d=p.material.draft||p,m=p.material;return `<div class="sw-card sw-pad"><div class="sw-row"><h2>${e(p.name)}</h2>${pill(m.status,m.status==='已核对'?'green':m.status==='退回补充'?'red':'orange')}</div>${facts([['身份证明',e(code(d.identity))],['手机号',e(code(d.phone))],['紧急联系人',e(d.emergency||m.emergency||'待补充')],['联系电话',e(code(d.emergencyPhone||m.emergencyPhone))]])}${m.reason?notice(e(m.reason),'warn'):''}${m.status==='待核对'?`<form data-form="material-review" data-person="${p.id}">${error()}${field('退回原因（通过时可留空）','reason')}${select('核对结果','result',['核对通过','退回补充'])}${btn('确认核对结果','submit','sw-primary sw-block')}</form>`:''}<div class="sw-buttons">${btn('游客填写入口','grant','',`data-id="${x.id}" data-person="${p.id}" data-scope="docs"`)}</div>${m.history.length?`<details class="sw-demo"><summary>材料记录</summary><ul class="sw-timeline">${m.history.map(h=>`<li>${e(h)}</li>`).join('')}</ul></details>`:''}</div>`;}).join('')}${notice('资料核对通过后交履约岗位承接，资料完整不代表已出票或签证通过。')}`;}
  function travelPage(){const x=o();return `<div class="sw-card sw-pad"><h2>${e(x.title)}</h2>${facts([['出发日期',x.date],['资源情况',e(x.resource)],['办理岗位','计调 · 周宁']])}</div>${x.notice?`<div class="sw-card sw-pad"><div class="sw-row"><h2>出团通知</h2>${pill('第'+x.notice.version+'版','green')}</div><p class="sw-small">发布于 ${x.notice.time}</p>${facts([['集合',e(x.notice.meet)],['领队',e(x.notice.leader)],['联系电话',e(x.notice.phone)],['酒店',e(x.notice.hotel)]])}${guestLinks(x,'travel')}</div>`:empty('出团通知尚未发布','计调发布后，可在本单查看集合和出行资料。')}`;}
  function applications(){const list=state.orders.filter(o=>o.owner===uid).flatMap(x=>[...x.claims.map(z=>({title:'认款 '+money(z.amount),sub:x.contact+' · '+z.status,view:'claim',id:x.id})),...(x.contract.status!=='未准备'?[{title:'合同办理',sub:x.contact+' · '+x.contract.status,view:'contract',id:x.id}]:[])]);return `<div class="sw-card">${list.map(x=>line(e(x.title),e(x.sub),x.view,x.id)).join('')||empty('暂无申请')}</div>`;}
  function account(){const a=M.actor(state,uid);return `<div class="sw-card sw-pad"><h1>${e(a.name)}</h1><p class="sw-small">${e(a.company)} · ${e(a.store)}</p>${facts([['岗位','销售顾问'],['范围','本人客户与本人订单'],['保存状态',storageOK?'本浏览器演示记录':'本次页面临时记录']])}</div><div class="sw-card sw-pad"><h2>演示场景</h2><p class="sw-small">以下仅切换原型结果，不执行真实支付、审批或资源操作。</p><form data-form="settings">${select('游客付款结果','payment',['成功','结果未知','失败'],state.settings.payment)}${select('合同平台受理','contract',['正常','结果未知'],state.settings.contract)}${btn('保存演示设置','submit','sw-block')}</form></div><form data-form="demo-result" class="sw-card sw-pad">${error()}<h2>接收下一岗位的示例结果</h2>${select('本次订单','oid',state.orders.filter(x=>x.owner===uid).map(x=>[x.id,x.contact+' · '+x.id]))}${select('示例事项','type',[['claim','财务认款复核'],['contract','合同审核／受理'],['seal','我方合同签章'],['payment','原笔付款核对'],['resource','计调资源确认'],['notice','发布出团通知']])}${select('结果','value',['通过','退回／失败'])}${btn('载入示例结果','submit','sw-soft sw-block')}</form><div class="sw-buttons">${btn('退出当前员工','logout')}${btn('重置本端演示','reset')}</div><p class="sw-footer">演示身份与本地记录不代表真实岗位鉴权<br>本端记录独立保存，不回写其他业务系统</p>`;}

  const params=new URLSearchParams(location.search), token=params.get('access'), sid=params.get('share');
  function guestActor(action){const pid=sessionStorage.getItem('sw-guest-'+token);if(!pid)throw Error('请先核对本次办理身份。');return M.access(state,token,pid,action);}
  function shareAllowed(){const v=M.shareView(state,sid);return !v.share.customerId||sessionStorage.getItem('sw-share-'+sid)===v.share.customerId;}
  function guestAuth(){const a=M.access(state,token);return `<div class="sw-result"><h1>继续您的出行办理</h1><p class="sw-small">核对本人手机号，查看本次订单。</p></div><form data-form="guest-auth" class="sw-card sw-pad">${error()}${field('办理人手机号','phone','','tel','maxlength="11"')}${field('验证码','code','','text','inputmode="numeric" maxlength="6"')}${btn('核对身份','submit','sw-primary sw-block')}<details class="sw-demo"><summary>演示身份</summary><p class="sw-small">${e(a.person.name)}：${e(a.person.phone)}<br>验证码：123456</p>${btn('填入演示身份','fill-guest')}</details></form>`;}
  function privateShare(){return `<div class="sw-result"><h1>您的专属出行推荐</h1><p class="sw-small">核对手机号后查看具体报价。</p></div><form data-form="share-auth" class="sw-card sw-pad">${error()}${field('客户手机号','phone','','tel','maxlength="11"')}${field('验证码','code','','text','inputmode="numeric"')}<p class="sw-small">原型验证码：123456</p>${btn('查看推荐','submit','sw-primary sw-block')}</form>`;}
  function recommend(){const v=M.shareView(state,sid);if(!shareAllowed())return privateShare();const {product:p,share:x,staff:a}=v;return `${hero(p)}${v.changed?notice(e(v.reason),'warn'):''}<div class="sw-card sw-pad">${facts(x.kind==='quote'?[['出发日期',x.date],['人数',x.adults+'成人'+(x.children?'、'+x.children+'儿童':'')],['参考总价',`<strong class="sw-price">${money(x.total)}</strong>`],['有效期',x.expires]]:[['出发地',e(p.from)],['参考价格',money(p.price)+'起 / 人']])}<p class="sw-small">具体出行安排、余位和费用，由顾问在预订前与您核对。</p></div>${section('行程安排')}${trip(p)}<div class="sw-card sw-pad"><div class="sw-row"><span class="sw-avatar">${e(a?.name.slice(-1)||'凯')}</span><div class="sw-line-body"><h3>${a?.active?e(a.name)+' · 您的旅游顾问':'门店接待'}</h3><p class="sw-small">${e(a?.company||'凯撒旅游')}</p></div></div>${a?.active?`<p class="sw-small sw-inline-meta">联系电话 ${e(a.phone)}</p>`:notice('原顾问暂不可接待，您的咨询将转门店分配。')}</div><div class="sw-dock">${btn('咨询本次出行','guest-consult','sw-primary sw-block')}</div>`;}
  function guestConsult(){const v=M.shareView(state,sid);if(!shareAllowed())return privateShare();if(route.done)return `<div class="sw-result"><div class="sw-result-icon">${icon('check')}</div><h1>咨询已提交</h1><p class="sw-small">${v.staff?.active?'您的顾问将与您核对本次需求。':'门店将为您安排顾问。'}</p></div>${btn('返回行程','guest-recommend','sw-primary sw-block')}`;return `<div class="sw-context">${e(v.product.name)}</div><form data-form="guest-consult" class="sw-card sw-pad">${error()}${field('您的姓名','name')}${field('联系手机号','phone','','tel','maxlength="11"')}${field('意向日期（未定可留空）','date',v.share.date||'','date',`min="${M.TODAY}"`)}${field('出行人数','pax',v.share.adults||2,'number','min="1" max="10"')}${area('想了解什么','note')}${check('同意接待顾问就本次出行联系我。','consent')}${btn('提交咨询','submit','sw-primary sw-block')}</form>`;}
  function guestHome(){const {order:x,person:p,grant:g}=guestActor(),m=M.amounts(x);return `<div class="sw-greeting"><h1>${e(p.name)}，您好</h1><p class="sw-small">您的出行进度都在这里。</p></div><div class="sw-card sw-pad"><div class="sw-row"><span class="sw-order-number">${x.id}</span>${pill(x.status,'blue')}</div><h2>${e(x.title)}</h2><p class="sw-small">${x.date} · ${x.people.length}位游客</p>${g.scope==='order'&&p.id===x.people[0].id?`<div class="sw-money-grid"><div><span>订单金额</span><strong>${money(x.total)}</strong></div><div><span>已确认收款</span><strong>${money(m.paid)}</strong></div><div><span>待收金额</span><strong>${money(m.unpaid)}</strong></div></div>`:''}</div><div class="sw-card">${g.scope==='order'&&p.id===x.people[0].id?line('付款与记录',m.inflight?'有付款结果待核对':m.pending?'转账款项核对中':m.unpaid?'查看本次应付安排':'已收齐','guest-pay','','wallet'):''}${['order','sign'].includes(g.scope)?line('我的合同',x.contract.status,'guest-sign','','file'):''}${['order','docs'].includes(g.scope)?line('我的出行资料',p.material.status,'guest-docs','','users'):''}${['order','travel'].includes(g.scope)?line('出团通知',x.notice?'第'+x.notice.version+'版':'暂未发布','guest-travel','','product'):''}</div><p class="sw-footer">仅展示您本人的办理资料<br>如需修改出行安排，请联系顾问</p>`;}
  function guestPay(){const {order:x}=guestActor('pay'),paymentReady=state.products.find(p=>p.id===x.productId)?.slots.find(t=>t.id===x.slotId)?.rules,m=M.amounts(x),last=x.payments.at(-1),amount=Math.min(m.available,m.paid<x.deposit?x.deposit-m.paid:m.unpaid);return `<div class="sw-card sw-pad"><h2>本单付款</h2>${facts([['产品',e(x.title)],['收款方',e(x.company)],['订单金额',money(x.total)],['已确认收款',money(m.paid)],['转账核对中',money(m.pending)],['付款结果待核对',money(m.inflight)]])}</div>${last?notice(last.status==='成功'?'原笔 '+money(last.amount)+' 付款成功，已计入本单收款。':last.status==='失败'?'原笔支付失败，未计入收款，可核对后重新支付。':'原笔付款结果待核对，请先查询结果，避免重复支付。',last.status==='成功'?'':'warn'):''}${x.status!=='已确认'?notice('订单尚未确认，本次收取为预收款，付款不代表资源或订单已经确认。','warn'):''}${!paymentReady?notice('本团期付款条件待确认，请先联系顾问。','warn'):m.inflight?btn('查询原笔付款结果','refresh-result','sw-primary sw-block'):m.available?`<form data-form="guest-pay" class="sw-card sw-pad">${error()}<div class="sw-row"><h3>${m.paid<x.deposit?'本次定金':'本次尾款'}</h3><span class="sw-price">${money(amount)}</span></div>${check('已核对收款方、金额及本单付款安排。')}${btn('确认模拟支付','submit','sw-primary sw-block')}</form>`:notice(m.pending?'转账认款正在核对，请等待结果。':'本单款项已收齐。')}<p class="sw-footer">业务演示，不发起真实扣款</p>${section('付款记录')}<div class="sw-card">${x.payments.map(p=>`<div class="sw-pad"><div class="sw-row"><strong>${money(p.amount)}</strong>${pill(p.status,p.status==='成功'?'green':'orange')}</div><p class="sw-small">${p.id} · ${p.at}</p></div>`).join('')||empty('暂无付款')}</div>`;}
  function contractPaper(x){const p=state.products.find(p=>p.id===x.productId);return `<div class="sw-contract-paper sw-legal"><h2>团队境内旅游合同</h2><p class="sw-small">第${x.contract.version}版 · 示例内容</p>${facts([['旅行社',e(x.company)],['旅游产品',e(x.title)],['出发日期',x.date],['合同总额',money(x.total)],['服务人数',x.people.length+'人']])}<h3>行程与费用附件</h3><p>${e(p.included)}</p><p>不包含：${e(p.excluded)}</p><p>成人 ${money(p.price)}／人，儿童占床 ${money(p.childPrice)}／人；本单单房差 ${money(x.supplement)}。</p><h3>付款约定</h3><p>本单定金 ${money(x.deposit)}，剩余款项在出发前按约定收齐。收款方为 ${e(x.company)}。</p><h3>退改办理</h3><p>${e(p.refund)}</p><h3>行程附件</h3>${p.itinerary.map(([t,d],i)=>`<p>第${i+1}天 · ${e(t)}：${e(d)}</p>`).join('')}<p class="sw-footer">仅用于演示阅读、核对和签署流程<br>正式合同以经审核的完整文本及附件为准</p></div>`;}
  function guestSign(){const {order:x,person:p}=guestActor('sign'),k=x.contract,self=k.signers.find(z=>z.personId===p.id);return `${notice('当前合同：'+e(k.status)+(self?' · 本人'+self.status:''),k.status==='已签署'?'':'warn')}${contractPaper(x)}${k.platform==='结果待核对'?notice('签署服务受理结果待核对，请稍后查询原合同。','warn')+btn('查询原合同结果','refresh-result','sw-primary sw-block'):self?.status==='已签署'?notice(k.status==='已签署'?'全部签署及我方签章已完成。':'您已签署，仍需其他签署人及我方签章完成。'):k.status==='签署中'?`<form data-form="guest-sign" class="sw-card sw-pad">${error()}${check('本人已阅读并确认本合同及行程、费用附件。')}${btn('确认本人模拟签署','submit','sw-primary sw-block')}</form>`:notice('顾问完成合同办理后，您可在这里继续签署。')}`;}
  function guestDocs(){const {person:p}=guestActor('docs'),m=p.material,d=m.draft||{...p,...m};return `<div class="sw-context">${e(p.name)} · 本人出行资料</div><div class="sw-row"><h2>资料状态</h2>${pill(m.status,m.status==='已核对'?'green':'orange')}</div>${m.reason?notice(e(m.reason),'warn'):''}${m.status==='已核对'||m.status==='待核对'?`<div class="sw-card sw-pad">${facts([['姓名',e(d.name)],['手机号',e(code(d.phone))],['身份证明',e(code(d.identity))],['紧急联系人',e(d.emergency||m.emergency)],['紧急联系电话',e(code(d.emergencyPhone||m.emergencyPhone))]])}</div>${notice(m.status==='已核对'?'资料已核对。如需修改，请联系您的顾问。':'资料已提交，等待顾问核对。')}`:`<form data-form="guest-docs" class="sw-card sw-pad">${error()}${field('姓名','name',d.name)}${field('手机号','phone',d.phone,'tel','maxlength="11"')}${field('身份证号','identity',d.identity,'text','maxlength="24"')}${field('紧急联系人','emergency',d.emergency)}${field('紧急联系人手机号','emergencyPhone',d.emergencyPhone,'tel','maxlength="11"')}${area('服务需求（如饮食、出行协助）','note',d.note)}${field('补充附件（可选，仅记录文件名）','file','','file','accept="image/*,.pdf"')}${d.file?`<p class="sw-small">已选附件：${e(d.file)}</p>`:''}<div class="sw-buttons">${btn('暂存','save-docs')}${btn('提交核对','submit','sw-primary')}</div><details class="sw-demo"><summary>演示资料</summary>${btn('填入示例资料','fill-docs')}</details></form>`}`;}
  function guestTravel(){const {order:x}=guestActor('travel');if(!x.notice)return empty('出团通知尚未发布','发布后可在这里查看集合和行程安排。',btn('查询通知','refresh-result'));return `<div class="sw-card sw-pad"><div class="sw-row"><h2>出团通知</h2>${pill('第'+x.notice.version+'版','green')}</div><p class="sw-small">${e(x.title)} · ${x.date}</p>${facts([['集合',e(x.notice.meet)],['领队',e(x.notice.leader)],['联系电话',e(x.notice.phone)],['酒店',e(x.notice.hotel)]])}</div>${trip(state.products.find(p=>p.id===x.productId))}`;}
  function refreshState(){try{const next=JSON.parse(localStorage.getItem(M.KEY));if(next?.version===1)state=next;}catch{}}
  function render(){route=parse();const primary=['home','products','customers','orders'].includes(route.view);let body='',title='',showNav=false,isLogin=false;try{if(guest){if(sid){title=route.view==='guest-consult'?'咨询顾问':'顾问推荐';body=route.view==='guest-consult'?guestConsult():recommend();}else if(token){M.access(state,token);if(!sessionStorage.getItem('sw-guest-'+token)){title='身份核对';body=guestAuth();}else{const views={'guest-home':[guestHome,'我的出行'],'recommend':[guestHome,'我的出行'],'guest-pay':[guestPay,'本单付款'],'guest-sign':[guestSign,'合同签署'],'guest-docs':[guestDocs,'出行资料'],'guest-travel':[guestTravel,'出团通知']};const view=views[route.view];if(!view)throw Error('此入口暂不可用。');title=view[1];body=view[0]();}}else{title='我的出行';body=empty('请从顾问分享的入口进入','产品推荐与订单办理分别使用独立入口。');}}else{try{M.actor(state,uid);}catch{uid='';}if(!uid){isLogin=true;body=login();}else{const views={home:[home,'销售工作台'],products:[products,'产品'],product:[productPage,'产品详情'],share:[sharePage,'推荐分享'],customers:[customers,'客户'],customer:[customerPage,'客户详情'],'new-customer':[newCustomer,'新客户'],intent:[intentPage,'本次意向'],'edit-intent':[intentEdit,'记录需求'],consult:[consultation,'接待咨询'],booking:[bookingPage,'办理预订'],orders:[orders,'订单'],order:[orderPage,'订单详情'],claim:[claimPage,'收款与认款'],contract:[contractPage,'合同办理'],materials:[materialsPage,'游客资料'],travel:[travelPage,'出行资料'],applications:[applications,'我的申请'],account:[account,'工作身份']};const view=views[route.view];if(!view)throw Error('页面不存在，请返回工作台。');title=view[1];body=view[0]();showNav=primary;}}}catch(err){body=empty('暂时无法办理',e(err.message),btn(guest?'返回入口':'返回工作台',guest?'guest-back':'home','sw-primary'));title='办理提示';}root.innerHTML=`<div class="sw-proto">业务原型 · 演示资料 · 不发起真实交易</div>${isLogin?'':titleBar(title,!showNav)}<main class="sw-main ${showNav?'sw-has-nav':''} ${['product','recommend'].includes(route.view)?'sw-has-dock':''}">${body}</main>${showNav?nav():''}`;document.title=title+' · 凯撒旅游';previous=location.hash;}
  function values(form){const v=Object.fromEntries(new FormData(form));for(const [k,x] of Object.entries(v)){if(x instanceof File)v[k]=x.name;}return v;}
  function fail(err,form){const box=form?.querySelector('.sw-form-error');if(box){box.textContent=err.message;box.scrollIntoView({block:'center',behavior:'smooth'});}else toast(err.message);}
  function complete(message,view,params={}){dirty=false;save();if(view)go(view,params);else render();if(message)toast(message);}
  function showGrant(id,person,scope){const g=M.grant(state,uid,id,person,scope),url=guestURL({access:g.token});save();dialog.innerHTML=`<h2>客户办理入口</h2><p>此入口供本单指定游客核对身份后办理。</p><div class="sw-code">${e(url)}</div><div class="sw-buttons">${btn('复制链接','copy','',`data-value="${e(url)}"`)}<a class="sw-button sw-primary" data-guest-link href="${e(url)}" target="_blank" rel="noopener">游客预览</a></div><div class="sw-buttons">${btn('关闭','dialog-cancel','sw-block')}</div>`;dialog.showModal();}
  function updateSearch(){if(route.view==='products'){const get=k=>root.querySelector(`[data-filter="${k}"]`)?.value||'',availability=get('availability'),date=get('date'),budget=Number(get('budget')),destination=get('destination');const list=state.products.filter(p=>p.active&&p.allowed.includes(uid)&&(p.name+p.destination).includes(query)&&(!budget||p.price<=budget)&&(destination==='全部目的地'||p.destination===destination)&&p.slots.some(s=>(!date||s.date===date)&&(availability!=='有位可订'||s.stock>0)&&(availability!=='二次确认'||s.mode==='二次确认')));root.querySelector('#productResults').innerHTML=list.map(p=>productRow(p,`data-cid="${e(route.cid||'')}" data-iid="${e(route.iid||'')}"`)).join('')||empty('没有符合条件的产品','可调整出行日期或预算。');}else if(route.view==='customers'){const list=state.customers.filter(x=>x.owner===uid&&(x.name+x.phone).includes(query));root.querySelector('#customerResults').innerHTML=customerTab==='客户'?list.map(customerRow).join('')||empty('未找到客户'):state.intents.filter(x=>x.owner===uid&&list.some(c=>c.id===x.customerId)).map(i=>line(e(c(i.customerId).name)+' · '+e(i.destination),e(i.stage),'intent',i.id)).join('')||empty('未找到意向');}else if(route.view==='orders')root.querySelector('#orderResults').innerHTML=orderRows(state.orders.filter(x=>x.owner===uid&&(filter==='全部'||x.status===filter)&&(x.id+x.contact+x.title).includes(query)));}
  document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();try{refreshState();const v=values(form);switch(form.dataset.form){case 'login':{if(v.code!=='123456')throw Error('验证码不正确。演示验证码为123456。');const a=state.staff.find(x=>x.phone===v.phone);M.actor(state,a?.id);uid=a.id;sessionStorage.setItem('sw-staff',uid);complete('已进入本人工作台','home');break;}
    case 'customer':{const x=M.saveCustomer(state,uid,v);complete('客户资料已保存','customer',{id:x.id});break;}
    case 'intent':{const x=M.saveIntent(state,uid,route.cid,v,route.id);complete('本次需求已保存','intent',{id:x.id});break;}
    case 'follow':M.followIntent(state,uid,route.id,v.text,v.follow,v.result==='关闭意向');complete('跟进已保存');break;
    case 'share':{const x=M.createShare(state,uid,{...v,productId:route.id});complete('推荐已生成','share',{id:route.id,sid:x.id});break;}
    case 'booking':{readBooking(form);if(step===1){syncQuote();if(booking.stock<booking.adults+booking.children)throw Error('余位不足，请调整日期或人数。');setPeople();step=2;dirty=false;render();}else if(step===2){c(booking.customerId);if(!booking.people.every((p,i)=>p.name&&(i>=booking.adults||M.phone(p.phone))))throw Error('请补齐游客姓名和每位成人的手机号。');syncQuote();step=3;dirty=false;render();}else{const x=M.submitBooking(state,uid,booking);booking=null;complete('预订已提交','order',{id:x.id});}break;}
    case 'claim':M.claim(state,uid,route.id,v,form.dataset.claim);complete('认款已提交，等待财务复核');break;
    case 'contract':M.prepareContract(state,uid,route.id,!!v.checked);complete('合同资料已提交审核');break;
    case 'material-review':M.reviewMaterial(state,uid,route.id,form.dataset.person,v.result==='核对通过',v.reason);complete('资料核对结果已保存');break;
    case 'settings':state.settings={payment:v.payment,contract:v.contract};complete('演示设置已保存');break;
    case 'demo-result':M.demoResult(state,uid,v.oid,v.type,v.value);complete('已载入示例结果');break;
    case 'share-auth':{const x=M.shareView(state,sid).share,person=state.customers.find(c=>c.id===x.customerId);if(v.code!=='123456'||person?.phone!==v.phone)throw Error('手机号或验证码与本次推荐客户不一致。');sessionStorage.setItem('sw-share-'+sid,person.id);dirty=false;render();break;}
    case 'guest-consult':if(!shareAllowed())throw Error('请先核对本次推荐身份。');M.consult(state,sid,v);complete('咨询已提交','guest-consult',{done:'1'});break;
    case 'guest-auth':{const pid=M.verifyGuest(state,token,v.phone,v.code);sessionStorage.setItem('sw-guest-'+token,pid);complete('身份已核对','guest-home');break;}
    case 'guest-pay':if(!v.checked)throw Error('请先核对收款方和本次付款安排。');M.pay(state,token,guestActor('pay').person.id);complete('已返回本次付款结果');break;
    case 'guest-sign':M.sign(state,token,guestActor('sign').person.id,!!v.checked);complete('本人签署已记录');break;
    case 'guest-docs':M.material(state,token,guestActor('docs').person.id,v,true);complete('资料已提交，等待顾问核对');break;
  }}catch(err){fail(err,form);}});
  document.addEventListener('click',async event=>{const el=event.target.closest('[data-action],[data-go]');if(!el||el.disabled)return;if(el.dataset.go){go(el.dataset.go);return;}const a=el.dataset.action,d=el.dataset,form=el.closest('form');if(a==='submit')return;event.preventDefault();try{if(a==='dialog-cancel'||a==='dialog-ok'){dialog.close();if(modalResolve){modalResolve(a==='dialog-ok');modalResolve=null;}return;}if(a==='copy'){await copyText(d.value);return;}if(a==='back'){back();return;}if(a==='noop')return;if(a==='login-user'){root.querySelector('[name="phone"]').value=state.staff.find(x=>x.id===d.id).phone;return;}if(['home','products','customers','orders','applications','new-customer'].includes(a)){go(a);return;}if(['product','customer','intent','consult','order','claim','contract','materials','travel'].includes(a)){go(a,{id:d.id,...(d.cid?{cid:d.cid,iid:d.iid||''}:{})});return;}if(a==='recommend'){go('products',{cid:d.cid,iid:d.iid||''});return;}if(a==='new-intent'){go('edit-intent',{cid:d.id});return;}if(a==='edit-intent'){go(a,{id:d.id,cid:d.cid});return;}if(a==='customer-tab'){customerTab=d.value;query='';render();return;}if(a==='order-filter'){filter=d.value;render();updateSearch();return;}if(a==='share-start'||a==='book-start'){const slot=root.querySelector('[name="slot"]:checked')?.value||'';dirty=false;if(a==='book-start'){if(!slot)throw Error('请先选择出发日期。');startBooking(d.id,slot,route.cid,route.iid);}else go('share',{id:d.id,slot,cid:route.cid||''});return;}if(a==='booking-prev'){readBooking(form);step--;dirty=false;render();return;}if(a==='save-booking'){readBooking(form);const saved=M.saveDraft(state,uid,booking);booking.draftId=saved.id;complete('预订草稿已保存','home');return;}if(a==='resume'){booking=M.copy(state.drafts.find(x=>x.id===d.id&&x.owner===uid));if(!booking)throw Error('草稿不存在。');booking.draftId=booking.id;step=1;go('booking');return;}if(a==='accept-consult'){const i=M.acceptConsult(state,uid,d.id);complete('本次咨询已接待','intent',{id:i.id});return;}if(a==='grant'){showGrant(d.id,d.person,d.scope);return;}if(a==='send-contract'){M.sendContract(state,uid,route.id);complete('请查看原合同受理结果');return;}if(a==='contract-preview'){dialog.innerHTML=contractPaper(o())+`<div class="sw-buttons">${btn('关闭','dialog-cancel','sw-primary sw-block')}</div>`;dialog.showModal();return;}if(a==='confirm-order'){if(await confirmDialog('确认本单','已核对资源、客户、费用与本单付款条件，继续确认？')){M.confirmOrder(state,uid,d.id);complete('订单已确认');}return;}if(a==='release'){if(await confirmDialog('释放保留名额','确认释放本单的预留／占位名额？已有款项、合同或资源确认时须另行办理。')){M.release(state,uid,d.id);complete('本单已取消，名额已释放');}return;}if(a==='logout'){if(dirty&&!confirm('尚有内容未保存，确认退出吗？'))return;sessionStorage.removeItem('sw-staff');uid='';dirty=false;go('home');return;}if(a==='reset'){if(await confirmDialog('重置本端演示','仅清除本销售工作台的演示记录，重新载入示例客户与订单。')){state=M.seed();booking=null;for(const key of Object.keys(sessionStorage))if(key.startsWith('sw-guest-')||key.startsWith('sw-share-'))sessionStorage.removeItem(key);complete('本端演示已重置','home');}return;}
    if(a==='guest-back'){dirty=false;go(token?'guest-home':'recommend');return;}if(a==='guest-recommend'){go('recommend');return;}if(['guest-consult','guest-pay','guest-sign','guest-docs','guest-travel'].includes(a)){go(a);return;}if(a==='fill-guest'){const x=M.access(state,token);form.elements.phone.value=x.person.phone;form.elements.code.value='123456';return;}if(a==='refresh-result'){refreshState();render();toast('已查询原记录，当前结果见页面');return;}if(a==='fill-docs'){const x=guestActor('docs');form.elements.identity.value=x.person.identity||'DEMO-0001';form.elements.emergency.value='陈红';form.elements.emergencyPhone.value='13900000005';form.elements.note.value='无特殊需求';dirty=true;return;}if(a==='save-docs'){M.material(state,token,guestActor('docs').person.id,values(form),false);complete('资料已暂存');return;}
  }catch(err){fail(err,form);}});
  document.addEventListener('input',event=>{const t=event.target;if(t.dataset.search){query=t.value.trim();updateSearch();return;}if(t.dataset.filter){updateSearch();return;}if(t.closest('form'))dirty=true;});
  document.addEventListener('change',event=>{const t=event.target;if(t.dataset.filter){updateSearch();return;}if(t.closest('form'))dirty=true;if(route.view==='booking'&&step===2&&t.name==='customerId'){booking.customerId=t.value;booking.people=[];setPeople();render();dirty=true;}});
  dialog.addEventListener('cancel',()=>{if(modalResolve){modalResolve(false);modalResolve=null;}});
  window.addEventListener('hashchange',()=>{if(dirty&&location.hash!==previous){if(!confirm('当前内容未保存，确认离开吗？')){history.replaceState(null,'',previous);return;}dirty=false;}render();window.scrollTo(0,0);});
  window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
  window.addEventListener('storage',event=>{if(event.key!==M.KEY)return;if(dirty){toast('有新的办理结果，保存当前内容后可查看');return;}refreshState();render();});
  save();render();
})();
